/* live2d-stub.min.js — Cubism 2 stub for pixi-live2d-display
 * Provides every global that pixi-live2d-display references at load-time
 * so the library initialises without "Cubism 2 runtime" errors.
 * No actual Cubism 2 functionality — the app uses Cubism 4 only.
 */
(function(){
    function noop(){}

    // AMotion base class (extended internally by the bundle)
    function AMotion(){}
    AMotion.prototype.setFadeIn  = noop;
    AMotion.prototype.setFadeOut = noop;
    AMotion.prototype.updateParam = noop;

    // Live2DMotion — patched by bundle right after the Cubism2 guard
    function Live2DMotion(){}
    Live2DMotion.prototype = Object.create(AMotion.prototype);
    Live2DMotion.prototype.constructor = Live2DMotion;
    Live2DMotion.prototype.updateParam = noop;
    Live2DMotion.loadMotion = function(){ return new Live2DMotion(); };

    // Live2DModelWebGL
    function Live2DModelWebGL(){}
    Live2DModelWebGL.prototype.getModelMatrix = function(){
        return { setWidth:noop, setPivot:noop };
    };

    // Physics helpers — bundle reads PhysicsHair.Src.{SRC_TO_X/Y/G_ANGLE} and PartsDataID.getID
    function PhysicsHair(){}
    PhysicsHair.Src = { SRC_TO_X: 0, SRC_TO_Y: 1, SRC_TO_G_ANGLE: 2 };

    function PartsDataID(){}
    PartsDataID.getID = function(){ return null; };

    // Expose every referenced Cubism 2 global
    window.AMotion            = AMotion;
    window.Live2D             = { getError: function(){ return 0; } };
    window.Live2DMotion       = Live2DMotion;
    window.Live2DModelWebGL   = Live2DModelWebGL;
    window.Live2DExpression   = function(){};
    window.Live2DEyeBlink     = function(){};
    window.Live2DPhysics      = function(){};
    window.Live2DPose         = function(){};
    window.Live2DTransform    = function(){};
    window.PhysicsHair        = PhysicsHair;
    window.PhysicsSettings    = function(){};
    window.PhysicsSettingCount = function(){};
    window.PhysicsSource      = {};
    window.PhysicsTargetType  = {};
    window.Physics            = function(){};
    window.DrawData           = function(){};
    window.DrawDataID         = function(){};
    window.DrawDataIndex      = function(){};
    window.PartsDataID        = PartsDataID;
    window.PartsDataIndex     = function(){};
})();
